let norm = (n:string) { iff(n matches regex @'^\d+\.\d', tolower(n), tolower(tostring(split(n, '.')[0]))) };
let providerMap = RASServer_CL | where Role == 'Provider' and isnotempty(IPAddress) | summarize arg_max(TimeGenerated, *) by IPAddress | project IPAddress, ProviderName = tolower(tostring(split(Computer, '.')[0]));
let srv = RASServer_CL | where Role !in ('RDSGroup','VDITemplate','VDIPool') | summarize arg_max(TimeGenerated, *) by Computer, Role | lookup kind=leftouter providerMap on IPAddress | extend NK = iff(Role == 'Provider' and isnotempty(ProviderName), ProviderName, norm(Computer));
let cpu = Perf | where TimeGenerated > ago(30m) | where ObjectName == 'Processor Information' and CounterName == '% Processor Time' | summarize CPU = avg(CounterValue) by NK = norm(Computer);
let mem = Perf | where TimeGenerated > ago(30m) | where CounterName == '% Committed Bytes In Use' | summarize RAM = avg(CounterValue) by NK = norm(Computer);
let ev  = Event | where TimeGenerated > ago(24h) | where (Source startswith 'Parallels' or Source == '2X Remote Application Server') or (Source == 'Microsoft-Windows-TerminalServices-LocalSessionManager' and EventID in (21, 23, 24, 25, 40)) | where EventLevelName in ('Error','Critical') | summarize Events24h = count() by NK = norm(Computer);
srv
| summarize Roles = strcat_array(make_set(Role), ', '), AgentVersion = any(AgentVersion), FarmName = any(FarmName), Computer = max(Computer) by NK
| join kind=leftouter cpu on NK
| join kind=leftouter mem on NK
| join kind=leftouter ev on NK
| project Computer, FarmName, Roles, AgentVersion, CPU = round(CPU, 0), RAM = round(RAM, 0), Events24h = coalesce(Events24h, 0)
| order by Events24h desc

let norm = (n:string) { iff(n matches regex @'^\d+\.\d', tolower(n), tolower(tostring(split(n, '.')[0]))) };
let hosts = RASServer_CL | where Role == 'RDSH' | summarize arg_max(TimeGenerated, *) by Computer | distinct norm(Computer);
Perf
| where TimeGenerated {TimeRange}
| where norm(Computer) in (hosts)
| where ObjectName == 'Processor Information' and CounterName == '% Processor Time'
| summarize CPU = avg(CounterValue) by bin(TimeGenerated, 5m), Computer
| order by TimeGenerated asc

